import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';

export interface LoginRequest {
  email: string;
  senha: string;
}

export interface RegisterRequest {
  nome: string;
  email: string;
  senha: string;
}

export interface AuthResponse {
  token: string;
  user: {
    id: number;
    nome: string;
    email: string;
  };
}

export interface UserData {
  id: number;
  nome: string;
  email: string;
  role?: number;
}

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private readonly API_URL = 'http://localhost/gfp/backend/api';
  private isLoggedInSubject = new BehaviorSubject<boolean>(this.checkToken());
  public isLoggedIn$ = this.isLoggedInSubject.asObservable();

  private isAdminSubject = new BehaviorSubject<boolean>(this.checkAdmin());
  public isAdmin$ = this.isAdminSubject.asObservable();

  constructor(private http: HttpClient) {}

  login(credentials: LoginRequest): Observable<AuthResponse> {
    return this.http.post<AuthResponse>(`${this.API_URL}/auth/login`, credentials)
      .pipe(
        tap((response: AuthResponse) => {
          localStorage.setItem('token', response.token);
          localStorage.setItem('user', JSON.stringify(response.user));
          this.isLoggedInSubject.next(true);
          this.isAdminSubject.next(this.checkAdmin());
        }),
        catchError((error: any) => {
          console.error('Login error:', error);
          throw error;
        })
      );
  }

  register(data: RegisterRequest): Observable<AuthResponse> {
    return this.http.post<AuthResponse>(`${this.API_URL}/auth/register`, data)
      .pipe(
        tap((response: AuthResponse) => {
          localStorage.setItem('token', response.token);
          localStorage.setItem('user', JSON.stringify(response.user));
          this.isLoggedInSubject.next(true);
          this.isAdminSubject.next(this.checkAdmin());
        }),
        catchError((error: any) => {
          console.error('Register error:', error);
          throw error;
        })
      );
  }

  logout(): void {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    this.isLoggedInSubject.next(false);
    this.isAdminSubject.next(false);
  }

  getToken(): string | null {
    return localStorage.getItem('token');
  }

  isAuthenticated(): boolean {
    return this.checkToken();
  }

  getUserData(): UserData | null {
    const userData = localStorage.getItem('user');
    if (!userData) return null;
    
    try {
      return JSON.parse(userData) as UserData;
    } catch {
      return null;
    }
  }

  private checkToken(): boolean {
    return !!localStorage.getItem('token');
  }

  private checkAdmin(): boolean {
    const user = localStorage.getItem('user');
    if (!user) return false;
    
    try {
      const parsed = JSON.parse(user);
      return parsed.admin === true || parsed.isAdmin === true;
    } catch {
      return false;
    }
  }
}
